WITH RecursiveTagCounts AS (
    SELECT 
        t.Id AS TagId, 
        t.TagName,
        COALESCE(p.Score, 0) AS PostScore,
        CAST(ARRAY[tp.Id] AS int[]) AS PostAnswers
    FROM Tags t
    LEFT JOIN Posts tp ON tp.Tags LIKE CONCAT('%<', t.TagName ,'>%') AND tp.PostTypeId = 1
    WHERE tp.PostTypeId = 1 AND tp.AnswerCount IS NOT NULL
),
TagAggregates AS (
    SELECT
        r.TagId,
        r.TagName,
        COUNT(*) AS QuestionCount,
        SUM(r.PostScore) AS TotalScore,
        AVG(r.PostScore) AS AvgScore
    FROM RecursiveTagCounts r
    GROUP BY r.TagId, r.TagName
),
